WITH cleaned AS (SELECT *, DAY(reading_ts) AS reading_ts_day FROM device_readings WHERE reading_ts >= DATE '2025-09-01'), deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY pressure, id) AS row_num FROM cleaned QUALIFY row_num = 1), gaps AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) > INTERVAL '20' MINUTE THEN 1 ELSE 0 END AS is_new_burst FROM deduped), sessions_device_readings AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps), remaining_keys AS (SELECT device_code FROM sessions_device_readings INTERSECT ALL SELECT device_code FROM device_readings WHERE temp_c IS NOT NULL), reconciled AS (SELECT s.* FROM sessions_device_readings s INNER JOIN remaining_keys k ON s.device_code = k.device_code) SELECT reading_ts, temp_c, pressure, status_bits, row_num, is_new_burst, session_id FROM reconciled ORDER BY status_bits, is_new_burst
